/// <reference lib="dom" />
/// <reference lib="dom.iterable" />

import {
  loadFont as loadInter,
  loadFont as loadSans,
} from "@remotion/google-fonts/Inter";
import { loadFont as loadSerif } from "@remotion/google-fonts/SourceSerif4";
import {
  AbsoluteFill,
  getRemotionEnvironment,
  Interactive,
  type InteractivitySchema,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
} from "react";
import {
  clampChroma,
  converter,
  formatRgb,
  interpolate,
  parse,
  type Rgb,
} from "culori";
import { loadFont as loadGeist } from "@remotion/google-fonts/Geist";
import { loadFont as loadInstrumentSerif } from "@remotion/google-fonts/InstrumentSerif";
import { loadFont as loadMontserrat } from "@remotion/google-fonts/Montserrat";
import { loadFont as loadOutfit } from "@remotion/google-fonts/Outfit";
import { loadFont as loadSpaceGrotesk } from "@remotion/google-fonts/SpaceGrotesk";

const toRgb = converter("rgb");

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function resolveColorString(s: string): string {
  const trimmed = s.trim();
  if (trimmed.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `mixOklch cannot resolve CSS variable "${trimmed}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return "#000";
  }
  if (!parse(trimmed)) {
    if (isDev()) {
      console.warn(`mixOklch could not parse "${trimmed}"; using black.`);
    }
    return "#000";
  }
  return trimmed;
}

function mixOklch(a: string, b: string, t: number): string {
  const mixed = clampChroma(
    interpolate([resolveColorString(a), resolveColorString(b)], "oklch")(t),
    "oklch",
    "rgb",
  );
  return toCss(toRgb(mixed));
}

function toCss(color: Rgb): string {
  return formatRgb(color);
}

/**
 * The type faces a scene's `fontFamily` may name.
 *
 * ## Why an allowlist and not a free string
 *
 * Every component in this registry loads its face through
 * `@remotion/google-fonts` rather than a CSS variable, for the reason spelled
 * out at the top of each one: a Remotion bundle has none of the app's CSS, so
 * `var(--font-…)` gets you the right face in the Player and a **fallback in the
 * mp4**. A bare family name handed to a component has exactly the same problem
 * — the browser preview finds it, the render does not, and the bug is invisible
 * until someone plays the file.
 *
 * So a name only counts as a font here if this module has loaded it. Values map
 * label → the real CSS family string `loadFont` returns, which is not always the
 * label ("Instrument Serif", not "InstrumentSerif").
 *
 * ## A raw stack still works
 *
 * `resolveFont` passes anything it does not recognise straight through, so a
 * caller who has loaded their own face — a brand font, a local `@font-face` —
 * names it directly and gets it. The allowlist is the safe path, not the only one.
 *
 * ponytail: all six load at module scope, so a render fetches six latin subsets
 * whether or not the video uses them. Move to a lazy per-family `loadFont()` if
 * bundle time ever shows up in a render trace.
 */
const FONTS: Record<string, string> = {
  Inter: loadInter("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Geist: loadGeist("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  "Space Grotesk": loadSpaceGrotesk("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Outfit: loadOutfit("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  Montserrat: loadMontserrat("normal", {
    weights: ["400", "500", "600", "700"],
    subsets: ["latin"],
  }).fontFamily,
  // 400 is the only weight this family ships. Asking for 600 throws.
  "Instrument Serif": loadInstrumentSerif("normal", {
    weights: ["400"],
    subsets: ["latin"],
  }).fontFamily,
};

/**
 * What a select control offers. `DEFAULT_FONT` first: a scene's own face is a
 * design decision, so the knob has to have an "off", and it has to be the
 * value it ships at.
 */
const DEFAULT_FONT = "Default";

/**
 * Label → loaded CSS family. Anything unrecognised passes through unchanged, so
 * a caller's own stack is never swallowed. `undefined` in, `undefined` out —
 * that is the signal for "keep the component's own face".
 */
const resolveFont = (name?: string): string | undefined =>
  !name || name === DEFAULT_FONT ? undefined : (FONTS[name] ?? name);

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#3072db", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#3072db",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#3072db", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#3072db",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

interface InputStyleContext {
  idleBorder: string;
  hoverBorder: string;
  activeBorder: string;
  invalidBorder: string;
  ring: string;
  invalidRing: string;
  background: string;
  hoverBackground: string;
  foreground: string;
  mutedForeground: string;
}

function inputStyleContext(theme: KitTheme): InputStyleContext {
  return {
    idleBorder: theme.input,
    hoverBorder: mixOklch(theme.input, theme.foreground, 0.18),
    activeBorder: theme.ring,
    invalidBorder: theme.destructive,
    ring: mixOklch(theme.background, theme.ring, 0.5),
    invalidRing: mixOklch(theme.background, theme.destructive, 0.4),
    background: theme.background,
    hoverBackground: mixOklch(theme.background, theme.muted, 0.4),
    foreground: theme.foreground,
    mutedForeground: theme.mutedForeground,
  };
}

// Loaded through @remotion/google-fonts, never a CSS variable — a Remotion
// bundle has none of the app's CSS, so a `var(--font-…)` gets you the right face
// in the Player and a fallback in the mp4 (design-system rule 4).
const { fontFamily: SERIF } = loadSerif("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const { fontFamily: SANS } = loadSans("normal", {
  weights: ["400", "500"],
  subsets: ["latin"],
});

export interface PromptZoomProps {
  /** The greeting above the field. */
  greeting?: string;
  /** Field placeholder, shown until the first character is typed. */
  placeholder?: string;
  /** The prompt that types itself once the cut has landed. */
  text?: string;
  /** Suggestion pills under the field. Empty by default — pass some to show
   *  them. They are static: the shot belongs to the typing and the cut. */
  chips?: string[];
  /** Model label in the field's footer, and the effort beside it. */
  model?: string;
  effort?: string;
  /** Seconds at which typing begins. */
  typeStart?: number;
  /** Seconds at which the view cuts. Not a transition — one frame. It lands
   *  *while the prompt is still being typed*, which is the whole gag. */
  cutAt?: number;
  /** Typing speed. 18 is what the reference measures. */
  charsPerSecond?: number;
  /** How far the cut pushes in. 2.547 is what the reference measures. */
  zoom?: number;
  /** Focal point of the cut, as a fraction of the frame. */
  focusX?: number;
  focusY?: number;
  /** The starburst mark. Defaults to `theme.primary`. */
  accentColor?: string;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /**
   * The face this scene paints its words in — a label from `fonts.ts`
   * ("Inter", "Space Grotesk", "Instrument Serif") or a CSS family you have
   * loaded yourself. Unset, the scene keeps the face it was designed around.
   *
   * Overrides `theme.fontFamily`, which is how a brand kit re-skins a whole
   * timeline from one value.
   */
  fontFamily?: string;
  speed?: number;
}

// --- Pure helpers (unit-tested) -------------------------------------------

/** Characters revealed by effective frame `fc`, clamped to `total`. */
function typedCount(
  fc: number,
  startF: number,
  perFrame: number,
  total: number,
): number {
  if (fc <= startF) return 0;
  if (perFrame <= 0) return total;
  return Math.min(total, Math.floor((fc - startF) * perFrame));
}

/**
 * The cut, as a hard boolean. There is no ramp and no easing on purpose.
 *
 * Measured on the reference: the wide view is intact on one frame and fully
 * pushed in on the very next (frames 39 → 40, 803ms → 824ms). Nothing in
 * between. Interpolating this — even over two or three frames — turns a cut into
 * a zoom, and the whole read of the shot is that it *snaps*.
 */
function isZoomed(fc: number, cutF: number): boolean {
  return fc >= cutF;
}

/**
 * Caret visibility. Solid whenever a character is actively landing, blinking on
 * a 1.06s cycle when it is not — which is what a real text caret does, and what
 * stops the shot looking frozen while the prompt waits to start.
 */
function caretOn(fc: number, fps: number, typing: boolean): boolean {
  if (typing) return true;
  const halfCycle = 0.53 * fps;
  return Math.floor(fc / halfCycle) % 2 === 0;
}

// --- Icons -----------------------------------------------------------------

function Glyph({
  d,
  size,
  color,
  fill,
}: {
  d: string;
  size: number;
  color: string;
  fill?: boolean;
}) {
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      fill={fill ? color : "none"}
      stroke={fill ? "none" : color}
      strokeWidth={1.8}
      strokeLinecap="round"
      strokeLinejoin="round"
      style={{ display: "block", flexShrink: 0 }}
    >
      <title>icon</title>
      <path d={d} />
    </svg>
  );
}

/** Paths for the default chip set, in order. */
const CHIP_ICONS = [
  "M12 20h9M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z", // pencil
  "M22 10 12 5 2 10l10 5 10-5ZM6 12v5c3 3 9 3 12 0v-5", // cap
  "m8 6-6 6 6 6M16 6l6 6-6 6", // code
  "M17 8h1a4 4 0 1 1 0 8h-1M3 8h14v9a4 4 0 0 1-4 4H7a4 4 0 0 1-4-4Z", // cup
  "M12 3v18M3 12h18M5.6 5.6l12.8 12.8M18.4 5.6 5.6 18.4", // spark
];

/**
 * The starburst that leads the greeting.
 *
 * Twelve rays with a solid hub, measured off the reference: they are roughly a
 * ninth of the mark's diameter and clearly separated, and their overlap at the
 * centre reads as a filled disc.
 *
 * Six bars, not twelve. A bar is centred on the origin so it draws a ray at both
 * ends — the first version stepped twelve bars by 15° and produced *twenty-four*
 * rays, which at a 19px mark is not a starburst, it is a dot.
 */
function Starburst({ size, color }: { size: number; color: string }) {
  const rays = Array.from({ length: 6 }, (_, i) => i * 30);
  return (
    <svg
      viewBox="0 0 24 24"
      width={size}
      height={size}
      style={{ display: "block", flexShrink: 0 }}
    >
      <title>Assistant</title>
      {rays.map((a) => (
        <rect
          key={a}
          x={10.9}
          y={1.6}
          width={2.2}
          height={20.8}
          rx={1.1}
          fill={color}
          transform={`rotate(${a} 12 12)`}
        />
      ))}
      <circle cx={12} cy={12} r={3.6} fill={color} />
    </svg>
  );
}

// --- Main composition ------------------------------------------------------

/**
 * An assistant's field that types a prompt into itself and, partway through the
 * sentence, **cuts** — hard, in a single frame — into the caret and keeps going.
 *
 * ## The cut is the component
 *
 * Everything here was taken off a frame-by-frame read of the reference, and the
 * one number that matters most is that the push-in happens between two adjacent
 * frames with nothing in between. It is a cut, not a move. The scale is
 * **2.547×** and it is anchored on a point that sits **10% across and 41% down
 * the input field** — which is exactly where the caret is.
 *
 * The typing starts *before* the cut and does not pause for it: the sentence is
 * already running when the frame snaps in, and carries straight on at the new
 * size. That is what stops the cut reading as a scene change — there is one
 * continuous action across it, and the cut just gets you closer to it.
 *
 * That focal point is over-determined by the measurement rather than guessed:
 * fitting the scale and centre to the field's top and left edges then predicts
 * the `+` glyph's centre to within 1.2px and the field's bottom edge to 0.0px.
 *
 * ## Layout is in the reference's own pixels
 *
 * The stage below is literally 810×450 — the recording's frame — scaled to fit
 * whatever composition it is given. Every position in it is a number measured
 * off that recording, so there is no second conversion to get wrong.
 *
 * ## What is not measured
 *
 * The colours and the wording. The reference is a specific product: its coral
 * mark, its model names, its suggestion labels. None of that belongs in a
 * component that ships to strangers and lands next to somebody else's `Input`
 * (design-system rule 5). The paint is the shadcn token set, the field takes its
 * surface from the `Input` primitive's own style context so the two cannot
 * drift, and every label is a prop.
 */
function PromptZoomScene({
  greeting = "Up late?",
  placeholder = "How can I help you today?",
  text = "Get me a plan for tomorrow",
  chips = [],
  model = "Auto",
  effort = "Medium",
  typeStart = 0.35,
  cutAt = 1,
  charsPerSecond = 18,
  zoom = 2.547,
  focusX = 0.27,
  focusY = 0.516,
  accentColor,
  theme,
  mode,
  fontFamily,
  speed = 1,
}: PromptZoomProps) {
  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const t = useKitTheme(theme, mode);
  const face = resolveFont(fontFamily ?? t.fontFamily) ?? SANS;
  const ui = inputStyleContext(t);
  const accent = accentColor ?? t.primary;

  const fc = frame * speed;

  // The reference's own frame. Laying out in these units means every number
  // below is one that was measured, not one that was converted.
  const REF_W = 810;
  const REF_H = 450;
  const stageScale = Math.min(width / REF_W, height / REF_H);

  // --- measured layout (recording px) ---
  const BOX = { x: 173, y: 197, w: 461, h: 86, r: 11 };
  const HEAD_Y = 145; // ink top of the greeting
  const HEAD_SIZE = 30; // ~28px ink height including descenders
  const MARK = 19;
  const CHIP_Y = 301;
  const CHIP_H = 26;
  const PAD = 20; // field's inner padding

  // A hairline is specified at a 40px control; this field is 86 tall, so the
  // token is walked toward the foreground through the system's own mix rather
  // than by picking a darker grey (design-system rule 3b). No drop shadow —
  // under a control this size a visible one is a grey smear (rule 3).
  const borderColor = mixOklch(ui.idleBorder, t.foreground, 0.18);

  // --- timeline ---
  const cutF = cutAt * fps;
  const zoomed = isZoomed(fc, cutF);
  const typedN = typedCount(
    fc,
    typeStart * fps,
    charsPerSecond / fps,
    text.length,
  );
  const typing = typedN > 0 && typedN < text.length;
  const typed = text.slice(0, typedN);
  const caret = caretOn(fc, fps, typing);

  const isRendering = getRemotionEnvironment().isRendering;
  const willChange = isRendering ? undefined : ("transform" as const);

  const chipRow =
    chips.length === 0 ? null : (
      <div
        style={{
          position: "absolute",
          left: BOX.x,
          top: CHIP_Y,
          width: BOX.w,
          display: "flex",
          justifyContent: "center",
          gap: 9,
        }}
      >
        {chips.map((chip, i) => {
          return (
            <div
              key={chip}
              style={{
                display: "inline-flex",
                alignItems: "center",
                gap: 5,
                height: CHIP_H,
                padding: "0 11px",
                borderRadius: CHIP_H / 2,
                background: t.card,
                border: `1px solid ${borderColor}`,
                color: t.foreground,
                fontFamily: face,
                fontWeight: 500,
                fontSize: 11,
                lineHeight: 1,
                whiteSpace: "nowrap",
                textRendering: "geometricPrecision",
              }}
            >
              <Glyph
                d={CHIP_ICONS[i % CHIP_ICONS.length]}
                size={12}
                color={t.mutedForeground}
              />
              {chip}
            </div>
          );
        })}
      </div>
    );

  return (
    <AbsoluteFill showInTimeline={false} style={{ background: t.background }}>
      <div
        style={{
          position: "absolute",
          left: "50%",
          top: "50%",
          width: REF_W,
          height: REF_H,
          transform: `translate(-50%, -50%) scale(${stageScale})`,
        }}
      >
        {/* The cut. A plain static scale about the caret — no interpolation, so
            there is never a frame of it "zooming". `transformOrigin` is the
            measured focal point, in the same units as everything else. */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `scale(${zoomed ? zoom : 1})`,
            transformOrigin: `${focusX * REF_W}px ${focusY * REF_H}px`,
            willChange,
          }}
        >
          {/* ---- Greeting */}
          <div
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: HEAD_Y - 6,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              gap: 12,
              fontFamily: SERIF,
              fontWeight: 400,
              fontSize: HEAD_SIZE,
              lineHeight: 1.1,
              color: t.foreground,
              textRendering: "geometricPrecision",
            }}
          >
            <Starburst size={MARK} color={accent} />
            {greeting}
          </div>

          {/* ---- The field */}
          <div
            style={{
              position: "absolute",
              left: BOX.x,
              top: BOX.y,
              width: BOX.w,
              height: BOX.h,
              borderRadius: BOX.r,
              background: t.card,
              border: `1px solid ${borderColor}`,
              boxShadow: "none",
            }}
          >
            {/* The prompt line, with the caret riding its end. */}
            <div
              style={{
                position: "absolute",
                left: PAD,
                top: PAD - 4,
                right: PAD,
                display: "flex",
                alignItems: "center",
                fontFamily: face,
                fontWeight: 400,
                fontSize: 12,
                lineHeight: 1.4,
                color: typedN > 0 ? t.foreground : t.mutedForeground,
                whiteSpace: "pre",
                textRendering: "geometricPrecision",
              }}
            >
              {typedN > 0 ? typed : placeholder}
              <span
                style={{
                  display: "inline-block",
                  width: 1.4,
                  height: 15,
                  marginLeft: 1,
                  background: t.foreground,
                  opacity: caret ? 1 : 0,
                }}
              />
            </div>

            {/* Footer: the add affordance, and the model readout. */}
            <div
              style={{
                position: "absolute",
                left: PAD,
                right: PAD,
                bottom: 12,
                display: "flex",
                alignItems: "center",
                justifyContent: "space-between",
                fontFamily: face,
                fontSize: 10,
                color: t.mutedForeground,
              }}
            >
              <Glyph d="M12 5v14M5 12h14" size={13} color={t.mutedForeground} />
              <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                <span style={{ color: t.foreground, fontWeight: 500 }}>
                  {model}
                </span>
                <span>{effort}</span>
              </div>
            </div>
          </div>

          {chipRow}
        </div>
      </div>
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
