  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const PromptZoomDefaults = {
  greeting: "Up late?",
  text: "Get me a plan for tomorrow",
  placeholder: "How can I help you today?",
  model: "Auto",
  effort: "Medium",
  typeStart: 0.35,
  cutAt: 1,
  zoom: 2.547,
  charsPerSecond: 18,
  focusX: 0.27,
  focusY: 0.516,
  accentColor: "#266DF0",
  mode: "light",
  speed: 1,
  theme: { background: "transparent" },
} satisfies Partial<PromptZoomElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const PromptZoomSchema = {
  greeting: {
    type: "text-content",
    default: "Up late?",
    description: "Greeting",
  },
  text: {
    type: "text-content",
    default: "Get me a plan for tomorrow",
    description: "Prompt",
  },
  placeholder: {
    type: "text-content",
    default: "How can I help you today?",
    description: "Placeholder",
  },
  model: { type: "text-content", default: "Auto", description: "Model" },
  effort: { type: "text-content", default: "Medium", description: "Effort" },
  accentColor: {
    type: "color",
    default: "#266DF0",
    description: "Accent",
    keyframable: false,
  },
  mode: {
    type: "enum",
    default: "light",
    description: "Mode",
    variants: { light: {}, dark: {} },
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function PromptZoomFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const PromptZoomInner = forwardRef<HTMLDivElement, PromptZoomElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...PromptZoomDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <PromptZoomFade>
            <PromptZoomScene key={key} {...rest} />
          </PromptZoomFade>
        </div>
      </Sequence>
    );
  },
);

export const PromptZoom = Interactive.withSchema({
  Component: PromptZoomInner,
  componentName: "<PromptZoom>",
  schema: PromptZoomSchema,
  wrapInSequence: true,
});
